# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">ERDEMLER TEMASI METİNLERİ VE DÜŞÜNCE YAZISI TÜRLERİ (T.8.3.26)</text>\n  <rect x="20" y="44" width="320" height="196" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">"Yanlışlarımız..." ve "Meşe ile Saz" Çözümlemesi</text>\n  <text x="180" y="90" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">1. "Yanlışlarımız..." (Okuma Metni — Deneme):</text>\n  <text x="180" y="108" text-anchor="middle" font-size="10" fill="#334155">• Konu: İnsanın kendi hatalarını kabul etme erdemi.</text>\n  <text x="180" y="124" text-anchor="middle" font-size="10" fill="#334155">• Ana Fikir: Yanlışlarımızı savunmak yerine onları fark edip</text>\n  <text x="180" y="140" text-anchor="middle" font-size="10" fill="#334155">düzeltmek (öz eleştiri) insanı olgunlaştırır.</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">2. "Meşe ile Saz" (Dinleme Metni — Fabl):</text>\n  <text x="180" y="182" text-anchor="middle" font-size="10" fill="#334155">• Meşe: Kibirli ve inatçı (fırtınada kökünden sökülür).</text>\n  <text x="180" y="198" text-anchor="middle" font-size="10" fill="#334155">• Saz: Alçakgönüllü ve esnek (eğilir ama kırılmaz).</text>\n  <text x="180" y="218" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Söz Sanatları: Kişileştirme (Teşhis) ve Konuşturma (İntak)</text>\n\n  <rect x="360" y="44" width="320" height="196" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Metin Türlerini Ayırt Etme (T.8.3.26)</text>\n  <text x="520" y="90" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Deneme (Ben&#39;in Ülkesi):</text>\n  <text x="520" y="106" text-anchor="middle" font-size="10" fill="#166534">Yazar kişisel görüşlerini kanıtlama amacı gütmeden,</text>\n  <text x="520" y="120" text-anchor="middle" font-size="10" fill="#166534">kendi kendisiyle konuşuyormuş gibi samimi yazar.</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Fıkra (Köşe Yazısı):</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10" fill="#166534">Güncel toplumsal olayları kanıtlama gereği duymadan</text>\n  <text x="520" y="172" text-anchor="middle" font-size="10" fill="#166534">gazete ve dergi köşelerinde yorumlayan kısa yazıdır.</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Makale (Nesnel ve Bilimsel):</text>\n  <text x="520" y="210" text-anchor="middle" font-size="10" fill="#166534">Bir tezi savunmak ve KANITLAMAK için belgelerle yazılır.</text>\n  <text x="520" y="226" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">• Roman ve Destan: Olay çevresinde gelişen türlerdir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">CÜMLENİN ÖGELERİ VE FİİLDE ÇATI GENEL UYGULAMALARI (T.8.4.18 &amp; T.8.4.19)</text>\n  <rect x="20" y="44" width="320" height="196" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Özne-Yüklem ve Nesne-Yüklem İlişkisi</text>\n  <text x="180" y="90" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">1. Özne-Yüklem İlişkisine Göre:</text>\n  <text x="180" y="108" text-anchor="middle" font-size="10" fill="#713f12">• Etken Fiil: İşi yapan gerçek/gizli özne bellidir (-l/-n yok).</text>\n  <text x="180" y="126" text-anchor="middle" font-size="10" fill="#713f12">• Edilgen Fiil: "-l / -n" eki alır, işi yapan belli değildir;</text>\n  <text x="180" y="142" text-anchor="middle" font-size="10" font-weight="bold" fill="#854d0e">etkilenen nesne "SÖZDE ÖZNE" olur!</text>\n  <text x="180" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">2. Nesne-Yüklem İlişkisine Göre:</text>\n  <text x="180" y="184" text-anchor="middle" font-size="10" fill="#713f12">• Geçişli Fiil: Nesne alabilir (Başına "ONU" gelir).</text>\n  <text x="180" y="202" text-anchor="middle" font-size="10" fill="#713f12">• Geçişsiz Fiil: Nesne alamaz (Başına "ONU" gelmez).</text>\n  <text x="180" y="222" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Altın Kural: Edilgen fiillerin tamamı GEÇİŞSİZDİR!</text>\n\n  <rect x="360" y="44" width="320" height="196" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">Çatı Dönüşümü ve Öge Analizi Örneği</text>\n  <text x="520" y="92" text-anchor="middle" font-size="10" font-weight="bold" fill="#581c87">Etken ve Geçişli Cümle:</text>\n  <text x="520" y="110" text-anchor="middle" font-size="10" fill="#6b21a8">"Görevliler (Özne) / salonu (Belirtili Nesne) /</text>\n  <text x="520" y="126" text-anchor="middle" font-size="10" fill="#6b21a8">sabahleyin (Zarf T.) / temizledi (Yüklem)."</text>\n  <text x="520" y="152" text-anchor="middle" font-size="10" font-weight="bold" fill="#581c87">Edilgen ve Geçişsiz Cümleye Dönüşümü:</text>\n  <text x="520" y="170" text-anchor="middle" font-size="10" fill="#6b21a8">"Salon (Sözde Özne) / görevlilerce (Zarf T. - Örtülü Özne) /</text>\n  <text x="520" y="186" text-anchor="middle" font-size="10" fill="#6b21a8">sabahleyin (Zarf T.) / temizlendi (Yüklem)."</text>\n  <text x="520" y="214" text-anchor="middle" font-size="10" font-weight="bold" fill="#be123c">Uyarı: İsim cümlelerinde çatı özelliği ARANMAZ!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">CÜMLEDE VURGU, ARA SÖZLER VE YAZIM-NOKTALAMA KURALLARI</text>\n  <rect x="20" y="44" width="320" height="196" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">Cümlede Vurgu ve Ara Söz Kullanımı</text>\n  <text x="180" y="92" text-anchor="middle" font-size="11" fill="#164e63">• Fiil Cümlesinde Vurgu: Yüklemden hemen</text>\n  <text x="180" y="108" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">ÖNCEKİ ÖGE vurgulanır (Yüklem başta ise yüklemde).</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" fill="#164e63">• İsim Cümlesinde Vurgu: Yüklemin kendisindedir.</text>\n  <text x="180" y="152" text-anchor="middle" font-size="11" fill="#164e63">• Soru ve "de/mi" Vurgusu: "mi" edatından önceki</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" fill="#164e63">kelimede veya soru sözcüğünün kendisindedir.</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">• Ara Söz: İki virgül (, ... ,) veya iki kısa çizgi</text>\n  <text x="180" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">(- ... -) arasında açıklayıcı olarak kullanılır.</text>\n\n  <rect x="360" y="44" width="320" height="196" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">Yazım ve Noktalama İpuçları (T.8.3.1)</text>\n  <text x="520" y="92" text-anchor="middle" font-size="11" fill="#881337">• Bağlaç olan "ki" ayrı yazılır; ancak kalıplaşmış</text>\n  <text x="520" y="110" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">SONBAHÇEM (sanki, oysaki, mademki, belki,</text>\n  <text x="520" y="128" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">hâlbuki, çünkü, meğerki) + illaki BİTİŞİK yazılır!</text>\n  <text x="520" y="152" text-anchor="middle" font-size="11" fill="#881337">• Bağlaç olan "da / de" her durumda ayrı yazılır ve</text>\n  <text x="520" y="168" text-anchor="middle" font-size="11" fill="#881337">ünsüz benzeşmesine uğrayıp "ta / te" olmaz.</text>\n  <text x="520" y="192" text-anchor="middle" font-size="11" fill="#881337">• Noktalı Virgül (;): Virgüllerle ayrılmış tür/takımları</text>\n  <text x="520" y="210" text-anchor="middle" font-size="11" fill="#881337">veya virgüllü özneden sonraki ögeleri ayırır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
